<?php require_once __DIR__.'/../../app/layout.php';if(empty($_SESSION['member_id']))redirect('/login.php');$s=$pdo->prepare('SELECT m.*,mt.name AS membership_type,mt.fee,mt.validity FROM members m LEFT JOIN membership_types mt ON mt.id=m.membership_type_id WHERE m.id=?');$s->execute([$_SESSION['member_id']]);$m=$s->fetch();if(!$m)redirect('/login.php');$fee=(float)($m['fee']??setting($pdo,'membership_fee','0'));
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$txn=trim($_POST['transaction_no']??'');if($fee<=0||!in_array($_POST['payment_mode']??'',['upi','bank','cash'],true)||($txn!==''&&strlen($txn)<4))throw new RuntimeException('Enter valid payment details.');$pdo->prepare('INSERT INTO membership_payments (member_id,amount,payment_mode,transaction_no,payment_date,proof_path) VALUES (?,?,?,?,?,?)')->execute([$m['id'],$fee,$_POST['payment_mode'],$txn?:null,$_POST['payment_date'],upload('proof')]);flash('Payment submitted for administrator verification.');redirect($m['status']==='active'?'/member/dashboard.php':'/login.php');}catch(Throwable $e){flash($e->getMessage()==='SQLSTATE[23000]: Integrity constraint violation: 1062 Duplicate entry'?'This transaction number was already used.':$e->getMessage(),'error');}}
header_html('Membership payment');?><h1>Membership fee payment</h1><p><strong><?=e($m['membership_type']??'Membership')?></strong> · <?=e($m['validity']??'')?><br>Fee payable: <strong>₹<?=e(number_format($fee,2))?></strong><br>UPI: <?=e(setting($pdo,'upi_id'))?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Amount<input type="text" value="₹<?=e(number_format($fee,2))?>" readonly></label><label>Mode<select name="payment_mode"><option value="upi">UPI / QR</option><option value="bank">Bank transfer</option><option value="cash">Cash</option></select></label><label>UTR / Transaction Number<input name="transaction_no" maxlength="100"></label><label>Payment date<input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></label><label>Proof (JPG, PNG, WEBP or PDF, max 5 MB)<input type="file" name="proof"></label><button>Submit for verification</button></form><?php footer_html();
